from marshmallow.fields import Field
import ipaddress

def get_ip_field_type(ip_cls):
    if issubclass(ip_cls, ipaddress.IPv4Address):
        return Field(type=ipaddress.IPv4Address)
    elif issubclass(ip_cls, ipaddress.IPv6Address):
        return Field(type=ipaddress.IPv6Address)
    else:
        raise ValueError("Unsupported IP address class")
